// OKF Workspace Generic - Custom Hook for Bundle State Management
// Generated by Mistral Vibe
// Co-Authored-By: Mistral Vibe <vibe@mistral.ai>

import { useState, useCallback, useMemo, useRef } from 'react';
import { parseFrontMatter } from '../utils/parseFrontMatter';
import { indexPDFInQdrant, removePDFFromQdrant } from '../utils/pdfIndexer';
import { saveBundle as saveBundleToZIP, importBundleFromZIP } from '../utils/bundleStorage';
import * as fsAccess from '../utils/fsAccess';
import { createDebouncedWriter } from '../utils/writeQueue';
import { SAMPLE_BUNDLE_CONFIG, SAMPLE_OKF_FILES, SAMPLE_GENERIC_INDEX, SAMPLE_GENERIC_LOG } from '../constants';

/**
 * Custom hook for managing bundle state
 * Encapsulates all bundle-related state and actions
 */
export function useBundle() {
  // ==========================================================================
  // STATE
  // ==========================================================================
  
  // Bundle configuration
  const [bundleConfig, setBundleConfig] = useState(null);
  
  // OKF files
  const [okfFiles, setOkfFiles] = useState([]);
  const [activeOKFId, setActiveOKFId] = useState(null);
  
  // PDF files (loaded in browser)
  const [pdfFiles, setPdfFiles] = useState({}); // { pdfId: {file: File, url: string} }
  const [activePDFId, setActivePDFId] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  
  // Side files (index and log). The raw setters only touch in-memory
  // state; the public setIndexContent/setLogContent (defined below) also
  // schedule an atomic disk write when a disk folder is connected.
  const [indexContent, setIndexContentRaw] = useState(SAMPLE_GENERIC_INDEX);
  const [logContent, setLogContentRaw] = useState(SAMPLE_GENERIC_LOG);
  
  // UI state
  const [layout, setLayout] = useState("3col");
  const [readOnly, setReadOnly] = useState(false);
  const [showInitializer, setShowInitializer] = useState(false);

  // Live disk connection (File System Access API). When diskConnected is
  // true, the currently loaded bundle mirrors a real folder on disk;
  // fileHandles maps each tracked filename ('index.md', 'log.md',
  // '<okfId>.md') to its FileSystemFileHandle for later writes.
  const [diskDirHandle, setDiskDirHandle] = useState(null);
  const [diskConnected, setDiskConnected] = useState(false);
  const [fileHandles, setFileHandles] = useState({});

  // Per-file live-save status: 'idle' | 'saving' | 'saved' | 'error',
  // keyed by 'index', 'log', or an OKF file id.
  const [saveStatus, setSaveStatus] = useState({});

  // ==========================================================================
  // DERIVED STATE
  // ==========================================================================
  
  // Active OKF file
  const activeOKF = useMemo(() => {
    return okfFiles.find(f => f.id === activeOKFId) || null;
  }, [okfFiles, activeOKFId]);
  
  // Active PDF file
  const activePDF = useMemo(() => {
    return pdfFiles[activePDFId]?.file || null;
  }, [pdfFiles, activePDFId]);
  
  // Metadata from active OKF
  const meta = useMemo(() => {
    if (activeOKF) {
      return parseFrontMatter(activeOKF.content);
    }
    return {};
  }, [activeOKF]);
  
  // Active PDF reference from bundle config
  const activePDFRef = useMemo(() => {
    if (bundleConfig && activePDFId) {
      return bundleConfig.pdfs.find(p => p.id === activePDFId) || null;
    }
    return null;
  }, [bundleConfig, activePDFId]);

  // ==========================================================================
  // LIVE DISK AUTOSAVE
  // ==========================================================================

  // Persists across renders: debounces writes per-file and guarantees at
  // most one in-flight write per file, so edits never interleave on disk.
  const writeQueueRef = useRef(null);
  if (writeQueueRef.current === null) {
    writeQueueRef.current = createDebouncedWriter(
      (_key, dirHandle, fileName, content) => fsAccess.writeFileAtomic(dirHandle, fileName, content),
      400,
      (key, status, err) => {
        setSaveStatus(prev => ({ ...prev, [key]: status }));
        if (status === 'error') {
          console.error(`Failed to save ${key} to disk:`, err);
        }
      }
    );
  }

  /**
   * If a disk folder is connected, marks the given file key as 'saving'
   * immediately and schedules a debounced atomic write of its content.
   * Lazily creates the file handle (and remembers it in fileHandles) the
   * first time a given filename is written. No-ops when no disk folder is
   * connected, leaving purely in-memory behavior unchanged.
   */
  const ensureFileHandleAndScheduleWrite = useCallback((key, fileName, content) => {
    if (!diskConnected || !diskDirHandle) return;
    setSaveStatus(prev => ({ ...prev, [key]: 'saving' }));
    (async () => {
      try {
        let handle = fileHandles[fileName];
        if (!handle) {
          handle = await fsAccess.getOrCreateFileHandle(diskDirHandle, fileName);
          setFileHandles(prev => ({ ...prev, [fileName]: handle }));
        }
        writeQueueRef.current(key, diskDirHandle, fileName, content);
      } catch (err) {
        setSaveStatus(prev => ({ ...prev, [key]: 'error' }));
        console.error(`Failed to prepare disk write for ${fileName}:`, err);
      }
    })();
  }, [diskConnected, diskDirHandle, fileHandles]);

  /**
   * Updates index.md content in memory and, when disk-connected, writes it
   * through atomically (debounced).
   */
  const setIndexContent = useCallback((content) => {
    setIndexContentRaw(content);
    ensureFileHandleAndScheduleWrite('index', 'index.md', content);
  }, [ensureFileHandleAndScheduleWrite]);

  /**
   * Updates log.md content in memory and, when disk-connected, writes it
   * through atomically (debounced).
   */
  const setLogContent = useCallback((content) => {
    setLogContentRaw(content);
    ensureFileHandleAndScheduleWrite('log', 'log.md', content);
  }, [ensureFileHandleAndScheduleWrite]);

  // ==========================================================================
  // ACTIONS
  // ==========================================================================

  /**
   * Initialize a new bundle
   */
  const createBundle = useCallback((config) => {
    setBundleConfig(config);
    setOkfFiles([]);
    setActiveOKFId(null);
    setPdfFiles({});
    setActivePDFId(null);
    setIndexContentRaw(SAMPLE_GENERIC_INDEX);
    setLogContentRaw(SAMPLE_GENERIC_LOG);
    setShowInitializer(false);
  }, []);

  /**
   * Load a bundle from file (supports both .zip and .json)
   */
  const loadBundle = useCallback(async (file) => {
    try {
      const isZip = file.name.toLowerCase().endsWith('.zip');
      
      if (isZip) {
        const result = await importBundleFromZIP(file);
        setBundleConfig(result.bundleConfig);
        setOkfFiles(result.okfFiles);
        setActiveOKFId(result.okfFiles[0]?.id || null);
        setPdfFiles({});
        setActivePDFId(null);
        setIndexContentRaw(result.indexContent || SAMPLE_GENERIC_INDEX);
        setLogContentRaw(result.logContent || SAMPLE_GENERIC_LOG);
        setShowInitializer(false);
      } else {
        // Legacy JSON support
        const reader = new FileReader();
        return new Promise((resolve, reject) => {
          reader.onload = (e) => {
            try {
              const data = JSON.parse(e.target.result);
              if (!data.bundle || !data.files) {
                throw new Error('Invalid bundle format');
              }
              setBundleConfig(data.bundle);
              setOkfFiles(data.files);
              setActiveOKFId(data.files[0]?.id || null);
              setPdfFiles({});
              setActivePDFId(null);
              setIndexContentRaw(SAMPLE_GENERIC_INDEX);
              setLogContentRaw(SAMPLE_GENERIC_LOG);
              setShowInitializer(false);
              resolve();
            } catch (err) {
              reject(err);
            }
          };
          reader.onerror = reject;
          reader.readAsText(file);
        });
      }
    } catch (err) {
      console.error('Failed to load bundle:', err);
      throw err;
    }
  }, []);

  /**
   * Open a bundle live from a real folder on disk via the File System
   * Access API. index.md and log.md are treated specially; every other
   * top-level .md file is loaded as an OKF fiche (its front-matter id, or
   * the filename if none, becomes the OKF id). A bundle.json at the folder
   * root is used for the bundle config if present, otherwise a minimal
   * config is synthesized from the folder name.
   *
   * On any failure (permission denied, picker cancelled, etc.) no bundle
   * state is mutated other than diskConnected, which is reset to false,
   * and the error is rethrown so the caller can surface it.
   */
  const openBundleFromDisk = useCallback(async () => {
    try {
      const dirHandle = await fsAccess.pickDirectory();

      const granted = await fsAccess.verifyPermission(dirHandle, 'readwrite');
      if (!granted) {
        throw new Error('Read-write permission to the selected folder was not granted');
      }

      const mdFiles = await fsAccess.listMarkdownFiles(dirHandle);

      const newFileHandles = {};
      let newIndexContent = SAMPLE_GENERIC_INDEX;
      let newLogContent = SAMPLE_GENERIC_LOG;
      const newOkfFiles = [];

      for (const { name, handle } of mdFiles) {
        newFileHandles[name] = handle;
        const content = await fsAccess.readFileText(handle);

        if (name === 'index.md') {
          newIndexContent = content;
        } else if (name === 'log.md') {
          newLogContent = content;
        } else {
          const meta = parseFrontMatter(content);
          const id = meta.id || name.replace(/\.md$/i, '');
          newOkfFiles.push({
            id,
            title: meta.title || id,
            ref_document: meta.ref_document || meta.ref_rccm || '',
            pages: meta.pages,
            status: meta.status || meta.statut || 'DRAFT',
            version: meta.version,
            author: meta.author || meta.auteur,
            updated_at: meta.updated_at || meta.date_maj,
            tags: meta.tags,
            related: meta.related || meta.liens,
            content
          });
        }
      }

      let newBundleConfig;
      try {
        const bundleJsonHandle = await dirHandle.getFileHandle('bundle.json', { create: false });
        const bundleJsonText = await fsAccess.readFileText(bundleJsonHandle);
        newBundleConfig = JSON.parse(bundleJsonText).bundle;
      } catch {
        const now = new Date().toISOString();
        newBundleConfig = {
          id: generateId('bundle'),
          name: dirHandle.name,
          description: '',
          path: dirHandle.name,
          createdAt: now,
          updatedAt: now,
          pdfs: []
        };
      }

      setDiskDirHandle(dirHandle);
      setFileHandles(newFileHandles);
      setBundleConfig(newBundleConfig);
      setOkfFiles(newOkfFiles);
      setActiveOKFId(newOkfFiles[0]?.id || null);
      setPdfFiles({});
      setActivePDFId(null);
      setIndexContentRaw(newIndexContent);
      setLogContentRaw(newLogContent);
      setShowInitializer(false);
      setDiskConnected(true);
    } catch (err) {
      setDiskConnected(false);
      console.error('Failed to open bundle from disk:', err);
      throw err;
    }
  }, []);

  /**
   * Save current bundle to ZIP file
   */
  const saveBundle = useCallback(() => {
    saveBundleToZIP(bundleConfig, okfFiles, indexContent, logContent);
  }, [bundleConfig, okfFiles, indexContent, logContent]);

  /**
   * Add a PDF file to the bundle and index it in Qdrant
   */
  const addPDF = useCallback(async (file, pageRange = null, onIndexingProgress) => {
    const pdfId = generateId('pdf');
    const url = URL.createObjectURL(file);
    
    // Add to pdfFiles state
    setPdfFiles(prev => ({
      ...prev,
      [pdfId]: { file, url }
    }));
    
    // Add to bundle config
    setBundleConfig(prev => {
      if (!prev) return null;
      
      const newPDFRef = {
        id: pdfId,
        name: file.name,
        path: file.name,
        pages: pageRange || { start: 1, end: 100, raw: "1-100" }
      };
      
      return {
        ...prev,
        pdfs: [...prev.pdfs, newPDFRef],
        updatedAt: new Date().toISOString()
      };
    });
    
    // Set as active PDF
    setActivePDFId(pdfId);
    setCurrentPage(1);
    
    // Index the PDF in Qdrant (fire and forget - don't block the UI)
    try {
      await indexPDFInQdrant(file, file.name, pdfId, onIndexingProgress);
    } catch (err) {
      console.error('Failed to index PDF in Qdrant:', err);
    }
    
    return pdfId;
  }, []);

  /**
   * Remove a PDF from the bundle and Qdrant index
   */
  const removePDF = useCallback(async (pdfId) => {
    // Get the PDF name before removing
    const pdfToRemove = bundleConfig?.pdfs.find(p => p.id === pdfId);
    const pdfName = pdfToRemove?.name;
    
    // Remove from pdfFiles
    setPdfFiles(prev => {
      const newPdfFiles = { ...prev };
      delete newPdfFiles[pdfId];
      return newPdfFiles;
    });

    // Remove from bundle config
    setBundleConfig(prev => {
      if (!prev) return null;
      return {
        ...prev,
        pdfs: prev.pdfs.filter(p => p.id !== pdfId),
        updatedAt: new Date().toISOString()
      };
    });

    // Update active PDF if needed, falling back to the first PDF
    // remaining *after* removal (not the stale pre-removal list)
    setActivePDFId(prevActiveId => {
      if (prevActiveId !== pdfId) return prevActiveId;
      const remaining = (bundleConfig?.pdfs || []).filter(p => p.id !== pdfId);
      return remaining[0]?.id || null;
    });
    
    // Remove from Qdrant index (fire and forget)
    if (pdfName) {
      try {
        await removePDFFromQdrant(pdfName);
      } catch (err) {
        console.error('Failed to remove PDF from Qdrant:', err);
      }
    }
  }, [bundleConfig]);

  /**
   * Set active PDF by ID
   */
  const setActivePDFById = useCallback((pdfId) => {
    setActivePDFId(pdfId);
    // Reset to first page when changing PDF
    setCurrentPage(1);
  }, []);

  /**
   * Add or update an OKF file. When a disk folder is connected, this also
   * writes the fiche through to disk atomically (debounced).
   */
  const saveOKFFile = useCallback((okfFile) => {
    setOkfFiles(prev => {
      const existingIndex = prev.findIndex(f => f.id === okfFile.id);
      if (existingIndex >= 0) {
        return [...prev.slice(0, existingIndex), okfFile, ...prev.slice(existingIndex + 1)];
      }
      return [...prev, okfFile];
    });
    setActiveOKFId(okfFile.id);
    ensureFileHandleAndScheduleWrite(okfFile.id, `${okfFile.id}.md`, okfFile.content);
  }, [ensureFileHandleAndScheduleWrite]);

  /**
   * Remove an OKF file
   */
  const removeOKFFile = useCallback((id) => {
    setOkfFiles(prev => prev.filter(f => f.id !== id));
    if (activeOKFId === id) {
      setActiveOKFId(null);
    }
  }, [activeOKFId]);

  /**
   * Apply edits from LLM.
   * Uses the functional form of setOkfFiles so we always read the
   * latest okfFiles / activeOKFId – no stale-closure risk. Each changed
   * part is also written through to disk atomically (debounced) when a
   * disk folder is connected.
   */
  const applyEdits = useCallback(({ fiche, index, log }) => {
    if (fiche) {
      setOkfFiles(prev => {
        const idx = prev.findIndex(f => f.id === activeOKFId);
        if (idx < 0) return prev;
        const updated = { ...prev[idx], content: fiche };
        return [...prev.slice(0, idx), updated, ...prev.slice(idx + 1)];
      });
      if (activeOKFId) {
        ensureFileHandleAndScheduleWrite(activeOKFId, `${activeOKFId}.md`, fiche);
      }
    }
    if (index) setIndexContent(index);
    if (log) setLogContent(log);
  }, [activeOKFId, ensureFileHandleAndScheduleWrite, setIndexContent, setLogContent]);

  /**
   * Re-reads every tracked file (index.md, log.md, each OKF fiche) from
   * disk and, for any whose content has changed and isn't currently being
   * written (saveStatus !== 'saving'), updates in-memory state to match.
   * The File System Access API has no push/watch notification, so this is
   * how external changes (e.g. edited in another program) make it back
   * into the UI — disk is always the source of truth. No-ops when no disk
   * folder is connected.
   */
  const syncFromDisk = useCallback(async () => {
    if (!diskConnected) return;

    for (const [fileName, handle] of Object.entries(fileHandles)) {
      const key = fileName === 'index.md' ? 'index'
        : fileName === 'log.md' ? 'log'
        : fileName.replace(/\.md$/i, '');

      if (saveStatus[key] === 'saving') continue;

      let diskContent;
      try {
        diskContent = await fsAccess.readFileText(handle);
      } catch (err) {
        console.error(`Failed to read ${fileName} from disk during sync:`, err);
        continue;
      }

      if (fileName === 'index.md') {
        if (diskContent !== indexContent) setIndexContentRaw(diskContent);
      } else if (fileName === 'log.md') {
        if (diskContent !== logContent) setLogContentRaw(diskContent);
      } else {
        setOkfFiles(prev => {
          const idx = prev.findIndex(f => f.id === key);
          if (idx < 0 || prev[idx].content === diskContent) return prev;
          const updated = { ...prev[idx], content: diskContent };
          return [...prev.slice(0, idx), updated, ...prev.slice(idx + 1)];
        });
      }
    }
  }, [diskConnected, fileHandles, saveStatus, indexContent, logContent]);

  /**
   * Initialize with sample data
   */
  const initWithSampleData = useCallback(() => {
    createBundle(SAMPLE_BUNDLE_CONFIG);
    setOkfFiles(SAMPLE_OKF_FILES);
    setActiveOKFId(SAMPLE_OKF_FILES[0]?.id || null);
  }, [createBundle]);

  // ==========================================================================
  // EFFECTS & SYNC
  // ==========================================================================
  
  // Sync activePDFId with bundle config when bundle changes
  // This ensures we always have a valid active PDF
  
  // ==========================================================================
  // RETURN
  // ==========================================================================
  
  return {
    // State
    bundleConfig,
    okfFiles,
    activeOKFId,
    activeOKF,
    pdfFiles,
    activePDFId,
    activePDF,
    activePDFRef,
    currentPage,
    indexContent,
    logContent,
    layout,
    readOnly,
    showInitializer,
    meta,
    diskDirHandle,
    diskConnected,
    fileHandles,
    saveStatus,

    // Setters
    setBundleConfig,
    setOkfFiles,
    setActiveOKFId,
    setPdfFiles,
    setActivePDFId,
    setCurrentPage,
    setIndexContent,
    setLogContent,
    setLayout,
    setReadOnly,
    setShowInitializer,

    // Actions
    createBundle,
    loadBundle,
    saveBundle,
    addPDF,
    removePDF,
    setActivePDFById,
    saveOKFFile,
    removeOKFFile,
    applyEdits,
    initWithSampleData,
    openBundleFromDisk,
    syncFromDisk
  };
}

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Generate a unique ID
 */
export function generateId(prefix = 'item') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`;
}

/**
 * Get PDF reference by name from bundle config
 */
export function getPDFRefByName(bundleConfig, name) {
  if (!bundleConfig) return null;
  return bundleConfig.pdfs.find(p => p.name === name) || null;
}

/**
 * Get OKF file by ID
 */
export function getOKFById(okfFiles, id) {
  return okfFiles.find(f => f.id === id) || null;
}
